INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
SELECT id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status FROM jsonb_populate_recordset(NULL::public.event, '[{"title": "朱棣在奉天殿受贺并宴群臣使者", "description": "永乐元年正月初一，朱棣在奉天殿接受朝贺，宴请群臣和属国使者。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月己卯朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "00708921-d167-5cea-93cc-7f9b35bd54c9"}, {"title": "朱棣祭祀太庙", "description": "朱棣于正月乙酉祭祀太庙。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月乙酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5ef1380b-c31a-5624-a9a0-5b53bf83f1ef"}, {"title": "明廷在南郊祭祀天地", "description": "明廷在南郊举行祭祀天地的大礼。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月辛卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "cbe2c7cf-ca18-565f-be0c-4db2938d9d10"}, {"title": "明廷恢复周齐代岷四王旧封", "description": "朝廷恢复周王朱橚、齐王朱榑、代王朱桂、岷王朱楩原有的封爵。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "07f1da47-6421-5a1c-95fd-b742128e85c0"}, {"title": "明廷定北平为北京", "description": "朝廷将北平定为北京。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "457c084d-3f05-5198-88ab-d068200f8077"}, {"title": "保定侯孟善镇守辽东", "description": "保定侯孟善奉命镇守辽东。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月癸巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c2dfe5b5-239e-5ee9-8644-f68184419cf6"}, {"title": "宋晟任平羌将军镇守甘肃", "description": "朝廷命宋晟为平羌将军，镇守甘肃。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年正月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0800742d-6c96-5532-bd70-cfcc65f00372"}, {"title": "明廷设置北京官署并改北平府为顺天府", "description": "朝廷在北京设留守行后军都督府、行部和国子监，改北平府名为顺天府。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月庚戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "199c2bf1-5ef0-54d4-8ad0-7f4b7a4dbf37"}, {"title": "明廷确立御史分巡各地的制度", "description": "朝廷派御史分别巡视各地，并把这一办法定为制度。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月乙卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d77a875d-7fd1-55d0-a670-5440b9e0f075"}, {"title": "宁王朱权徙封南昌", "description": "朝廷将宁王朱权的封地迁到南昌。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月己未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "22b3c182-a826-56cb-b000-e7ba3b238eb7"}, {"title": "明廷致书鬼力赤可汗", "description": "朝廷致书鬼力赤可汗，表示准许他派遣使者往来通好。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0b167fae-732e-5ca5-9be3-1bce3d29ddcb"}, {"title": "朱棣行耕耤礼", "description": "朱棣举行亲耕耤田的仪式。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月癸亥", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "569163e6-9a6b-5932-a8ea-bdea76d73280"}, {"title": "明廷派使者往乌斯藏召请哈立麻", "description": "朝廷派使者去乌斯藏召请本纪所称尚师哈立麻。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月乙丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "0cd76438-9d33-52ee-892e-e1c0797b9a71"}, {"title": "明廷赈济北京六府饥荒", "description": "北京辖下六府发生饥荒，朝廷下令赈济。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a5091408-9547-5fca-95f8-e7f8ded87a4f"}, {"title": "明廷令司法官署每五日奏报罪囚", "description": "朝廷命负责司法的官署，每五日引见罪囚并奏报。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "11d305eb-38a3-5dac-bd39-a1451fd77114"}, {"title": "明廷命掩埋战地遗骨", "description": "朝廷下令掩埋暴露在战地的遗骨。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月壬申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "f6f6da3d-6d66-58ea-9641-82241130be4a"}, {"title": "高阳王朱高煦在开平备边", "description": "高阳王朱高煦在开平部署边防。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年二月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ada07230-1319-52b5-828b-6f51cad81f0f"}, {"title": "江阴侯吴高镇守大同", "description": "江阴侯吴高奉命镇守大同。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年三月庚辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9211d559-db63-58d8-8087-38c4996f154d"}, {"title": "明廷改设大宁都司并迁往保定", "description": "朝廷将北平行都司改为大宁都司，迁驻保定，并将大宁地方交给兀良哈。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年三月壬午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2ac5fda2-6fd0-55c3-a133-d186d8ad4316"}, {"title": "陈瑄和宣信督办辽东北京海运粮饷", "description": "朝廷命平江伯陈瑄和都督佥事宣信任总兵官，督办海运，供应辽东与北京粮饷，此后按年施行。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年三月戊子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "41b4cf79-57a8-5a50-b7b5-5a4ca280e3d6"}, {"title": "明廷赈济直隶北京山东河南饥荒", "description": "朝廷下令赈济直隶、北京、山东和河南的饥荒。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年三月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "64cd2e90-7647-5085-8f26-b6212f40ee4c"}, {"title": "安南胡𡗨请求袭爵，明廷派使核查", "description": "四月初一，安南的胡𡗨请求承袭陈氏的封爵。朝廷派使者调查，并要求据实上报。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年四月丁未朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "4b067f55-b363-513c-906d-775763b18044"}, {"title": "夏原吉在苏州、松江治理水患", "description": "永乐元年（年号对照1403年）四月，夏原吉在苏州、松江治理水患。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年（年号对照1403年）四月；公元年核为1403年。", "dynasty": "明", "location_name": null, "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": null, "status": "draft", "id": "3177f954-9637-5f6b-a473-792dff7f68ab"}, {"title": "明廷因岷王获罪而降其属官", "description": "岷王朱楩获罪，朝廷降处其所属官员。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年四月辛未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a357db2f-d43f-568d-8172-504cec599c21"}, {"title": "襄城伯李濬镇守江西", "description": "襄城伯李濬奉命镇守江西。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年四月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "b2ce0052-480b-554a-813b-b45baa35633b"}, {"title": "明廷免去各地未开垦荒田的额税", "description": "朝廷免去尚未开垦的荒田按额应征之税。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年五月丁丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5943a9f6-b76b-5c5a-9a6f-d6c6b8aef811"}, {"title": "明廷下令对死罪以下囚犯减一等刑", "description": "朝廷下令，对判死罪及以下的囚犯依等次各减刑一等。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年五月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "5690a2b4-b660-5acf-9617-767da8d128ab"}, {"title": "明廷命捕治山东蝗虫", "description": "朝廷下令扑捕山东的蝗虫。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年五月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "7509f2c4-4b10-505d-aa7f-831b8616e991"}, {"title": "河南发生蝗灾，朝廷免去当年夏税", "description": "河南发生蝗灾，朝廷免去当年夏税。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年五月丁酉", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "930aa607-b77f-58db-bd5d-8ddbdcc861e6"}, {"title": "明廷再次按靖难功赏袁容陈懋等", "description": "朝廷再次评定靖难功劳，封驸马都尉袁容等三人为侯，封陈亨之子陈懋等六人为伯。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年五月", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "9b3f4eda-10ee-5c49-822c-2acef6a22883"}, {"title": "代王朱桂获罪，其护卫被削", "description": "代王朱桂获罪，朝廷削去他的护卫。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年六月壬子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1a73df02-bf11-5d42-8445-a3d335ad98f2"}, {"title": "明廷分派给事中和御史巡视各地", "description": "朝廷派给事中和御史分赴各地，安抚军民，逮捕查办贪赃违法的官员。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年六月癸丑", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ea2e0d8f-8b2b-54e9-8df7-c711db44147f"}, {"title": "明廷更改高皇帝高皇后的尊谥", "description": "朝廷重新为高皇帝和高皇后上尊谥。本段未列出新谥号的全文。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年六月丁巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "eeec1df3-e55b-5aae-936c-5a18e611a45d"}, {"title": "武安侯郑亨镇守宣府", "description": "武安侯郑亨奉命镇守宣府。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年六月戊辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "e85efff0-7829-506d-9c8f-7289c1a5088f"}, {"title": "明廷再次致书鬼力赤", "description": "朝廷在七月庚寅再次致书鬼力赤。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年七月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "96d6462f-e239-544f-9586-85a40aa8fd93"}, {"title": "明廷发流罪以下罪犯到北京垦田", "description": "朝廷发遣判流罪及以下的罪犯到北京垦荒耕田。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年八月己巳", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "1812515f-d2b8-5bf0-8c4d-b32dfeba01ba"}, {"title": "明廷迁各地富户到北京", "description": "朝廷从直隶苏州等十郡和浙江等九省迁富户到北京。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年八月甲戌", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "ba4e1389-93c6-5885-bc08-da7490d4e7b3"}, {"title": "明廷命宝源局铸农具发给山东灾民", "description": "朝廷命宝源局铸造农具，发给山东因战乱陷入贫困的百姓。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年九月癸未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "324623c9-64da-5438-808a-b806c56f872a"}, {"title": "明廷首次派中官马彬出使爪哇等国", "description": "朝廷首次派中官马彬出使爪哇等国。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年九月庚寅", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "658ee74a-ed3d-59fc-bda1-839a06f2f0d5"}, {"title": "盛庸被夺爵", "description": "朝廷夺去历城侯盛庸的爵位。本纪随后记盛庸自杀，未单列具体日。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年九月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "c8e75ca4-84b5-5f63-8167-93c8df573ce9"}, {"title": "岷王朱楩获罪，其护卫被削", "description": "岷王朱楩获罪，朝廷削去他的护卫。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年九月庚子", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "09545ad6-6ac1-50ee-87c3-e3dff58e1b38"}, {"title": "明廷向朝鲜等国颁历并确立成例", "description": "十一月初一，朝廷向朝鲜等国颁发历书，并将其定为成例。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年十一月乙亥朔", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "d3624696-fc9f-54cc-819e-d16337ab7473"}, {"title": "明廷遣散疏浚河道的民夫", "description": "朝廷停止征用疏浚河道的民夫，并遣散已征用的民夫。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年十一月壬辰", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a893664d-492b-5af6-a4a7-18b1bdd4f2fd"}, {"title": "北京发生地震", "description": "本纪记北京在十一月甲午发生地震。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年十一月甲午", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "a7c556ea-fdf8-566d-be15-7c029284ca26"}, {"title": "明廷命六科办事官报告政事", "description": "朝廷命六科办事官就政事陈述意见。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年十一月乙未", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "67d116b5-c7eb-5c87-a2d4-c01274bb1149"}, {"title": "韩观平定柳州山地战事", "description": "本纪记载，韩观征讨柳州山地武装，并平定战事。", "start_year": 1403, "end_year": 1403, "time_original": "永乐元年十一月丙申", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "78bee705-c9c1-51ad-b81e-2ac11a53ac22"}, {"title": "明廷封胡𡗨为安南国王", "description": "朝廷于闰十一月丁卯封胡𡗨为安南国王。", "start_year": 1404, "end_year": 1404, "time_original": "永乐元年闰十一月丁卯", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "2cb73d68-9f86-5302-873d-192ca6e8642e"}, {"title": "明廷开始派内臣出镇并监督京营", "description": "本纪记载，朝廷这一年开始派内臣到地方出镇，并监督京营军队。 按原历纪年，事情发生在公元1403至1404年之间。", "start_year": null, "end_year": null, "time_original": "永乐元年", "dynasty": "明", "location_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_modern_name": null, "location_note": null, "status": "draft", "id": "6496859e-30f7-554e-ad91-535c45204eac"}, {"title": "朝鲜与琉球等地向明廷入贡", "description": "本纪记朝鲜这一年来贡六次，自此按岁时来贡